from common import *
import pandas as pd,hashlib
o=ROOT/"phase41";protocol=json.loads((o/"protocol.json").read_text());assert json.loads((o/"diagnostic_audit.json").read_text())["status"]=="PASS";assert json.loads((o/"feature_causality_audit.json").read_text())["status"]=="PASS";people=pd.read_csv(o/"loso_people.csv");summary=pd.read_csv(o/"loso_summary.csv");decisions=[];fixed=["KEEP","WRITE","RESET","low_entropy_write","anchor_guard"]
for lr,g in summary.groupby("lr"):
 best=float(g[g.policy.isin(fixed)].utility.max())
 for _,row in g[g.policy.str.startswith("future")].iterrows():
  h=people[(people.lr==lr)&(people.policy==row.policy)];positive=int((h.utility>0).sum());matched="current"+row.policy[len("future"):];current=g[g.policy==matched];decisions.append(dict(lr=lr,policy=row.policy,mean_utility=float(row.utility),best_fixed=best,positive_people=positive,matched_current_policy=matched,matched_current_utility=float(current.utility.iloc[0]) if len(current) else None,advance=bool(row.utility>best and positive>=3)))
(o/"advance_decisions.json").write_text(json.dumps(dict(criterion=protocol["advance_diagnostic_rule"],decisions=decisions),indent=2));counts=[];maxerr=0.;total=0;budgets={}
for path in sorted(o.glob("lr*/complete.json")):
 meta=json.loads(path.read_text());assert meta["checkpoint_sha256"]==hashlib.sha256((ROOT/"phase35/mixed/model.pt").read_bytes()).hexdigest();z=np.load(path.parent/"pulses.npz");yy=z["future_labels"];sid=meta["subject"];root=ROOT/("data/processed" if sid<20 else "phase2/processed");raw=np.load(root/f"s{sid:02d}_meta.npz")["y"];assert np.array_equal(yy,np.stack([raw[t+1:t+5] for t in z["t"]]));budget=budgets.setdefault(sid,dict(current=set(),future=set()));budget["current"].update(z["t"].tolist());budget["future"].update(z["future_labels_used"].tolist());a=z["future_keep"];assert np.isfinite(a).all() and abs(a.sum(-1)-1).max()<1e-5;idx=np.indices(yy.shape);base=-np.log(np.clip(a[idx[0],idx[1],yy],1e-38,1));ap=a.argmax(-1)
 for action,col in [("reset",0),("commit",1)]:
  b=z["future_"+action];assert np.isfinite(b).all() and abs(b.sum(-1)-1).max()<1e-5;loss=-np.log(np.clip(b[idx[0],idx[1],yy],1e-38,1));gain=(base-loss).mean(1);err=float(abs(gain-z["future_gain"][:,col]).max());assert err<2e-5;maxerr=max(maxerr,err);bp=b.argmax(-1);counts.append(dict(subject=sid,trajectory=meta["trajectory"],action=action,pulses=len(yy),ce_gain=float(gain.mean()),accuracy_gain_pp=float(100*((bp==yy).astype(float)-(ap==yy)).mean()),changed=int((ap!=bp).sum()),corrected=int(((ap!=yy)&(bp==yy)).sum()),harmed=int(((ap==yy)&(bp!=yy)).sum())))
 total+=len(yy)
c=pd.DataFrame(counts);c.to_csv(o/"classification_diagnostics.csv",index=False);labelbudgets=[dict(subject=sid,current_unique_labels=len(b["current"]),future_unique_labels=len(b["future"])) for sid,b in budgets.items()];pd.DataFrame(labelbudgets).to_csv(o/"label_budgets.csv",index=False);(o/"probability_audit.json").write_text(json.dumps(dict(status="PASS",pulses=total,max_ce_gain_error=maxerr,raw_future_labels_verified=True,checkpoint_hashes_verified=True,classification_counts_recomputed=True),indent=2))
m=pd.read_csv(o/"mechanism_summary.csv");adv=[v for v in decisions if v["advance"]];style='<style>body{font:15px/1.65 system-ui;max-width:1350px;margin:30px auto}td,th{padding:5px;border-bottom:1px solid #ccc}section{overflow:auto}</style>'
html='<!doctype html><html lang="zh"><meta charset="utf-8">'+style+'<h1>固定分类器辅助头：混合来源动态保留诊断</h1><p>根据阶段37源验证固定LR0.01，在查看阶段40迁移结果前记录本协议。四名既有源控制器，连续更新与每64窗口重置；每20窗口比较保留、提交写入和重置对未来4窗口的影响。436维输入仅含当前可见信号，未来/当前标签分别用于离线监督目标。</p>'+f'<p>完成8条轨迹、{total}次脉冲，分类概率和CE独立复算通过，特征未来扰动和历史前缀审计通过。满足预设源验证推进条件的候选数：{len(adv)}。</p><p>按人留一、等受试者权重；未来与当前目标使用相同容量预测器，包括4/21/36/436特征Ridge与36特征浅树，以及限制动作对照。未来标签数量更大，当前对照只匹配容量；若推进真实策略验证，还需相同未来标签预算的静态校准对照。四人已反复观察，不能称作新盲测。</p><h2>写入与重置效用</h2><p>CE收益单位nats。RESET挽回积累的损害不是新鲜WRITE收益；oracle使用未来标签，不能把脉冲收益相加当成在线F1。</p><section>'+m.to_html(index=False,float_format=lambda x:f"{x:.7f}")+'</section><h2>预设推进判定</h2><section>'+pd.DataFrame(decisions).to_html(index=False,float_format=lambda x:f"{x:.7f}")+'</section><h2>动作的分类正确数变化</h2><section>'+c.to_html(index=False,float_format=lambda x:f"{x:.7f}")+'</section><p><a href="loso_people.csv">逐人控制器结果</a> · <a href="probability_audit.json">概率审计</a> · <a href="feature_causality_audit.json">因果特征审计</a> · <a href="label_budgets.csv">标签预算</a></p></html>';(o/"report.html").write_text(html);print("ADVANCE",len(adv),adv);print("PULSES",total,"MAX_ERROR",maxerr)
